  (20, 'COLORANT', 'Exclusively or mainly intended to colour the cosmetic product, the body as a whole or certain parts thereof, by absorption or reflection of visible light; (precursors of oxidative hair colorants shall be deemed colorants). All authorised colorants are substances in the positive list of Annex IV to the Cosmetics Regulation 1223/2009.', '6749715b-b26c-4199-9e85-39361ce2808e'::uuid, '{"apiVersion":"2.151","reference":"6749715b-b26c-4199-9e85-39361ce2808e","url":"urn:test","contentType":"text/plain","language":"en","databaseLabel":"Growth Cosmetic Ingredients and Substances","database":"GROWTH_COSING","summary":"","weight":0.0,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"itemType":["function"],"es_ContentType":["text/plain"],"es_SortDate":["2023-05-10T16:05:26.295+0200"],"functionName":["COLORANT"],"esST_DATASOURCE":["GROWTH_COSING"],"esDA_IngestDate":["2023-05-10T16:05:26.349+0200"],"language":["en"],"esST_checksum":["E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855"],"url":["urn:test"],"corporate-search-version":["102"],"esST_URL":["urn:test"],"esDA_QueueDate":["2023-05-10T16:05:26.325+0200"],"functionId":["20"],"esST_FileName":["file.txt"],"datasource":["GROWTH_COSING"],"functionDescription":["Exclusively or mainly intended to colour the cosmetic product, the body as a whole or certain parts thereof, by absorption or reflection of visible light; (precursors of oxidative hair colorants shall be deemed colorants). All authorised colorants are substances in the positive list of Annex IV to the Cosmetics Regulation 1223/2009."]},"enrichedMetadata":{},"children":[],"highlightedFragments":[],"citation":"6749715b-b26c-4199-9e85-39361ce2808e. Available at: urn:test"}'::jsonb),
