  (102, 'DISPERSING NON-SURFACTANT', 'Facilitating the dispersion of solids in liquids. They function primarily by coating the solid through the process of adsorption, thus changing the surface characteristic of the suspended solid.', '4f3f218a-d582-4f0a-8c44-5d1ba1fab651'::uuid, '{"apiVersion":"2.151","reference":"4f3f218a-d582-4f0a-8c44-5d1ba1fab651","url":"urn:test","contentType":"text/plain","language":"en","databaseLabel":"Growth Cosmetic Ingredients and Substances","database":"GROWTH_COSING","summary":"","weight":0.0,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"itemType":["function"],"es_ContentType":["text/plain"],"es_SortDate":["2023-05-10T16:05:27.268+0200"],"functionName":["DISPERSING NON-SURFACTANT"],"esST_DATASOURCE":["GROWTH_COSING"],"esDA_IngestDate":["2023-05-10T16:05:27.382+0200"],"language":["en"],"esST_checksum":["E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855"],"url":["urn:test"],"corporate-search-version":["102"],"esST_URL":["urn:test"],"esDA_QueueDate":["2023-05-10T16:05:27.356+0200"],"functionId":["102"],"esST_FileName":["file.txt"],"datasource":["GROWTH_COSING"],"functionDescription":["Facilitating the dispersion of solids in liquids. They function primarily by coating the solid through the process of adsorption, thus changing the surface characteristic of the suspended solid."]},"enrichedMetadata":{},"children":[],"highlightedFragments":[],"citation":"4f3f218a-d582-4f0a-8c44-5d1ba1fab651. Available at: urn:test"}'::jsonb),
